// 五表只追加真实业务来源；完整旧行逐值保持，实际cache/history后绑定，不从空增量推测玩家权限。
#include "task_message_return_receipts.hpp"
#include "task_message_return_detail.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {namespace {
using namespace message_return_detail;
struct Source {StableId fact_id,kind,actor_id,action_id,task_id,reason;Integer tick=0;bool start=false,success=true;const TaskMessageReturnResult* result=nullptr;bool effect_task_id_present=true;std::optional<StableId> on_unavailable,retry;};
Source source(const TaskMessageReturnState& state,const StableId& id){if(const auto* s=state.starts.find(id))return {id,task_message_return_started_kind,s->carrier_actor_id,s->action_id,s->task_id,{},s->started_tick,true,true,s->actual_result?&*s->actual_result:nullptr};if(const auto* e=state.collections.find(id)){const auto* s=state.starts.find(e->start_fact_id);if(!s)return {};return {id,e->success?task_message_return_collected_kind:task_message_return_interrupted_kind,s->carrier_actor_id,e->action_id,e->task_id,e->reason,e->tick,false,e->success,e->actual_result?&*e->actual_result:nullptr};}if(const auto* d=state.deliveries.find(id)){const auto* e=state.collections.find(d->collection_fact_id);const auto* s=e?state.starts.find(e->start_fact_id):nullptr;if(!s)return {};return {id,task_message_return_delivered_kind,s->carrier_actor_id,d->source_action_id,d->task_id,{},d->tick,false,true,d->actual_result?&*d->actual_result:nullptr};}if(const auto* r=state.report_starts.find(id))return {id,task_message_return_report_started_kind,r->carrier_actor_id,r->action_id,r->task_id,{},r->started_tick,true,true,r->actual_result?&*r->actual_result:nullptr};if(const auto* r=state.report_interruptions.find(id)){const auto* start=state.report_starts.find(r->report_start_fact_id);if(!start)return {};Source out{id,task_message_return_report_interrupted_kind,start->carrier_actor_id,r->action_id,r->task_id,r->reason,r->tick,false,false,r->actual_result?&*r->actual_result:nullptr};out.effect_task_id_present=r->effect_task_id_present;out.on_unavailable=r->on_unavailable;out.retry=r->retry;return out;}return {};}
std::optional<TaskMessageReturnResult>* binding(TaskMessageReturnState& state,const StableId& id){if(auto* s=state.starts.find(id))return &s->actual_result;if(auto* s=state.collections.find(id))return &s->actual_result;if(auto* s=state.deliveries.find(id))return &s->actual_result;if(auto* s=state.report_starts.find(id))return &s->actual_result;if(auto* s=state.report_interruptions.find(id))return &s->actual_result;return nullptr;}
bool clock_kind(const StableId& kind){return kind=="advance"||kind=="wait"||kind=="travel_wait"||kind=="duel_start"||kind=="encounter_fight"||kind=="dialogue_confirm";}
bool clock_shape(const StableId& kind,const ReceiptDetails& details){if(kind=="advance"||kind=="wait"||kind=="travel_wait")return std::holds_alternative<AdvanceDetails>(details.data);if(kind=="duel_start"||kind=="encounter_fight"){const auto* p=std::get_if<PersonalReceipt>(&details.data);return p&&!p->battle_id.empty();}if(kind=="dialogue_confirm")return std::holds_alternative<Done>(details.data)||std::holds_alternative<AdvanceDetails>(details.data)||(std::holds_alternative<PersonalReceipt>(details.data)&&!std::get<PersonalReceipt>(details.data).battle_id.empty());return false;}
Status actual(const Source& s,const StableId& actor,const StableId& kind,Integer tick,Integer from,const ReceiptDetails& details){if(s.fact_id.empty()||s.tick!=tick)return common_failure("TaskMessageReturnActualSourceRequired",s.fact_id);if(s.start){const auto* a=std::get_if<ActionStarted>(&details.data);return kind==(s.kind==task_message_return_report_started_kind?StableId{"report_offer"}:StableId{task_message_return_collect_command})&&s.actor_id==actor&&from==tick&&a&&a->action_id==s.action_id?common_success():common_failure("TaskMessageReturnActualStartRequired",s.fact_id);}if(from<0||from==std::numeric_limits<Integer>::max()||from+1!=tick||!clock_kind(kind)||!clock_shape(kind,details))return common_failure("TaskMessageReturnActualClockRequired",s.fact_id);
 // 明文Advance携带逐Action真结果；隐藏推进的原Personal/Done形状仍由真正前后差分绑定，不伪造Advance。
 if(const auto* advance=std::get_if<AdvanceDetails>(&details.data)){const auto* e=advance->completed_actions.find(s.action_id);if(!e||!e->ok||e->completed||e->success||e->already_completed||e->code||e->military||e->family||e->growth||!e->military_field_order.empty()||!e->task||e->task->task_id!=(s.effect_task_id_present?std::optional<StableId>{s.task_id}:std::optional<StableId>{})||e->task->success!=s.success||e->task->code!=(s.success?std::optional<StableId>{}:std::optional<StableId>{s.reason})||e->task->on_unavailable!=s.on_unavailable||e->task->retry!=s.retry)return common_failure("TaskMessageReturnActualCompletionRequired",s.fact_id);}return common_success();}
template<class T>bool trim(const OrderedTable<T>& before,OrderedTable<T>& after,std::vector<StableId>& ids){if(after.size()<before.size())return false;for(std::size_t i=0;i<before.size();++i)if(before.order()[i]!=after.order()[i])return false;std::vector<StableId> added(after.order().begin()+before.size(),after.order().end());for(const auto& id:added){ids.push_back(id);after.erase(id);}return true;}
std::vector<StableId> ordered(const CommonStore& c,const TaskMessageReturnState& s){std::vector<StableId> out;for(const auto& row:c.state().facts.rows())if(s.starts.find(row.first)||s.collections.find(row.first)||s.deliveries.find(row.first)||s.report_starts.find(row.first)||s.report_interruptions.find(row.first))out.push_back(row.first);return out;}
std::size_t count(const TaskMessageReturnState& s){return s.starts.size()+s.collections.size()+s.deliveries.size()+s.report_starts.size()+s.report_interruptions.size();}
}
Outcome<std::vector<StableId>> task_message_return_new_result_sources(const TaskMessageReturnState& before,const TaskMessageReturnState& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick,Integer before_tick){auto fail=[]()->Outcome<std::vector<StableId>>{return {false,{},common_failure("TaskMessageReturnNewSourceRequired").error};};if(before.version!=1||after.version!=1)return fail();auto old=after;std::vector<StableId> ids;if(!trim(before.starts,old.starts,ids)||!trim(before.collections,old.collections,ids)||!trim(before.deliveries,old.deliveries,ids)||!trim(before.report_starts,old.report_starts,ids)||!trim(before.report_interruptions,old.report_interruptions,ids)||!compare_boundary(encode_task_message_returns(before),encode_task_message_returns(old)).exact())return fail();for(const auto* table:{&before.starts})for(const auto& row:table->rows())if(!row.second.actual_result)return fail();for(const auto& row:before.collections.rows())if(!row.second.actual_result)return fail();for(const auto& row:before.deliveries.rows())if(!row.second.actual_result)return fail();for(const auto& row:before.report_starts.rows())if(!row.second.actual_result)return fail();for(const auto& row:before.report_interruptions.rows())if(!row.second.actual_result)return fail();
 if(kind==task_message_return_collect_command&&ids.size()!=1)return fail();if(kind=="report_offer"&&ids.size()>1)return fail();if(!ids.empty()&&kind!="report_offer"&&kind!=task_message_return_collect_command&&(!clock_kind(kind)||before_tick<0||before_tick==std::numeric_limits<Integer>::max()||before_tick+1!=tick))return fail();std::vector<std::pair<Integer,StableId>> sort;
 for(const auto& id:ids){const auto s=source(after,id);if(s.result)return fail();auto valid=actual(s,actor,kind,tick,before_tick,details);if(!valid.ok)return {false,{},valid.error};const auto colon=id.find(':');Integer n=0;if(colon==StableId::npos)return fail();const auto text=id.substr(colon+1);auto p=std::from_chars(text.data(),text.data()+text.size(),n);if(p.ec!=std::errc{}||p.ptr!=text.data()+text.size()||n<1||std::to_string(n)!=text)return fail();sort.emplace_back(n,id);}std::sort(sort.begin(),sort.end());ids.clear();for(const auto& row:sort)ids.push_back(row.second);return {true,std::move(ids),{}};}
Status validate_task_message_return_results(const TaskMessageReturnSources& x){const auto& c=x.common;const auto& state=x.state;if(state.version!=1)return common_failure("UnsupportedTaskMessageReturnVersion");if(x.submitter_mode!=TaskMessageReturnSubmitterMode::controlled_player&&x.submitter_mode!=TaskMessageReturnSubmitterMode::legacy_actor)return common_failure("TaskMessageReturnSubmitterModeRequired");auto phase=through(c,x.phase);if(!phase.ok)return {false,{},phase.error};auto ids=ordered(c,state);if(ids.size()!=count(state))return common_failure("TaskMessageReturnResultSourceRequired");std::set<Integer> fact_numbers;for(const auto& row:c.state().facts.rows()){const auto at=row.first.find(':');if(at!=StableId::npos){auto number=serial(c,row.first,row.first.substr(0,at));if(number)fact_numbers.insert(*number);}}
 Integer last_fact=0,last_result=0,last_revision=0;StableId group;std::set<StableId> groups;std::map<StableId,Integer> requests;TaskMessageReturnResult previous;bool group_start=false,pending=false;
 for(const auto& id:ids){const auto s=source(state,id);const auto* head=c.state().facts.find(id);if(!head||head->id!=id||head->kind!=s.kind||head->domain!=task_message_return_module)return common_failure("TaskMessageReturnPermanentResultRequired",id);if(!s.result){const auto n=serial(c,id,s.kind);if(!x.phase||s.start||s.tick!=x.phase->to_tick||!n||*n<=last_fact||*n<=last_result)return common_failure("TaskMessageReturnPermanentResultRequired",id);pending=true;last_fact=*n;continue;}if(pending)return common_failure("TaskMessageReturnBoundAfterPendingCompletion",id);const auto& b=*s.result;const auto fact=serial(c,id,s.kind),result=serial(c,b.result_id,"result");const auto* request=c.state().request_sequences.find(b.request_actor_id);if(!fact||!result||*fact<=last_fact||*result<=*fact||fact_numbers.count(*result)||!request||!c.actor(b.request_actor_id)||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*request||b.result_revision<1||b.result_revision>c.revision()||b.result_tick!=s.tick||b.result_tick>c.tick())return common_failure("InvalidTaskMessageReturnResult",id);last_fact=*fact;
  const bool same=b.result_id==group;if(!same){if(!groups.insert(b.result_id).second||*fact<=last_result||*result<=last_result||b.result_revision<=last_revision||b.request_sequence<=requests[b.request_actor_id])return common_failure("TaskMessageReturnResultOrderMismatch",id);group=b.result_id;last_result=*result;last_revision=b.result_revision;requests[b.request_actor_id]=b.request_sequence;previous=b;group_start=s.start;}else if(group_start||s.start||b.request_actor_id!=previous.request_actor_id||b.command_kind!=previous.command_kind||b.request_sequence!=previous.request_sequence||b.result_revision!=previous.result_revision||b.from_tick!=previous.from_tick||b.result_tick!=previous.result_tick)return common_failure("TaskMessageReturnAmbiguousResultGroup",id);
  if(s.start){if(b.command_kind!=(s.kind==task_message_return_report_started_kind?StableId{"report_offer"}:StableId{task_message_return_collect_command})||b.request_actor_id!=s.actor_id||b.from_tick!=s.tick)return common_failure("TaskMessageReturnStartSubmitterMismatch",id);}else if(!clock_kind(b.command_kind)||b.from_tick<0||b.from_tick==std::numeric_limits<Integer>::max()||b.from_tick+1!=s.tick)return common_failure("TaskMessageReturnClockMismatch",id);
  if(x.submitter_mode==TaskMessageReturnSubmitterMode::controlled_player){if(!x.player_before)return common_failure("TaskMessageReturnPlayerSourceRequired",id);auto player=x.player_before(s.tick,id);if(!player.ok)return {false,{},player.error};if(player.value!=b.request_actor_id)return common_failure("TaskMessageReturnHistoricalSubmitterMismatch",id);}
  const HistoryRecord* prior=nullptr;const HistoryRecord* lower=nullptr;Integer found=0;for(const auto& h:c.state().history){if(h.result_id==b.result_id){lower=prior;if(++found>1||h.actor_id!=b.request_actor_id||h.kind!=b.command_kind||h.tick!=b.result_tick)return common_failure("TaskMessageReturnHistoryMismatch",id);}prior=&h;}if(lower){const auto low=serial(c,lower->result_id,"result");if(!low||*low>=*fact)return common_failure("TaskMessageReturnResultAllocationMismatch",id);}const auto* cached=c.state().results.find(b.request_actor_id+":"+std::to_string(b.request_sequence));if(cached){if(found!=1||!*cached||!(*cached)->ok||!(*cached)->details||(*cached)->result_id!=b.result_id||(*cached)->revision!=b.result_revision||(*cached)->kind!=b.command_kind)return common_failure("TaskMessageReturnCacheMismatch",id);auto valid=actual(s,b.request_actor_id,(*cached)->kind,(*cached)->tick,b.from_tick,*(*cached)->details);if(!valid.ok)return valid;}
 }
 for(const auto& h:c.state().history)if(h.kind==task_message_return_collect_command){Integer found=0;for(const auto& row:state.starts.rows())if(row.second.actual_result&&row.second.actual_result->result_id==h.result_id)++found;if(found!=1)return common_failure("TaskMessageReturnCachedStartSourceRequired",h.result_id);}
 for(const auto& row:c.state().results.rows())if(row.second&&row.second->kind==task_message_return_collect_command){const auto& r=*row.second;const TaskMessageReturnStart* found=nullptr;for(const auto& entry:state.starts.rows())if(entry.second.actual_result&&entry.second.actual_result->result_id==r.result_id){if(found)return common_failure("DuplicateTaskMessageReturnCachedStart",row.first);found=&entry.second;}if(!found||!found->actual_result||row.first!=found->actual_result->request_actor_id+":"+std::to_string(found->actual_result->request_sequence)||!r.ok||!r.details)return common_failure("TaskMessageReturnCachedStartSourceRequired",row.first);auto valid=actual(source(state,found->fact_id),found->actual_result->request_actor_id,r.kind,r.tick,found->actual_result->from_tick,*r.details);if(!valid.ok)return valid;}
 return common_success();}
Status bind_task_message_return_results(CommonStore& c,TaskMessageReturnState& state,const TaskMessageReturnSources& x,const std::vector<StableId>& ids,const StableId& actor,Integer request,const CommitResult& result,Integer before_tick){if(&c!=&x.common||&state!=&x.state)return common_failure("TaskMessageReturnCandidateRequired");if(ids.empty())return result.kind==task_message_return_collect_command?common_failure("TaskMessageReturnNewSourceRequired"):common_success();const auto* cached=c.state().results.find(actor+":"+std::to_string(request));const auto* seq=c.state().request_sequences.find(actor);if(!result.ok||!result.details||result.tick!=c.tick()||result.revision!=c.revision()||!cached||cached->get()!=&result||!seq||*seq!=request||c.state().history.empty())return common_failure("TaskMessageReturnActualResultRequired");const auto& h=c.state().history.back();if(h.actor_id!=actor||h.kind!=result.kind||h.tick!=result.tick||h.result_id!=result.result_id)return common_failure("TaskMessageReturnActualHistoryRequired");std::set<StableId> seen;std::vector<std::optional<TaskMessageReturnResult>*> changes;
 for(const auto& id:ids){auto* target=binding(state,id);if(!target||*target||!seen.insert(id).second)return common_failure("TaskMessageReturnNewSourceRequired",id);auto valid=actual(source(state,id),actor,result.kind,result.tick,before_tick,*result.details);if(!valid.ok)return valid;changes.push_back(target);}for(auto* target:changes)*target=TaskMessageReturnResult{result.result_id,actor,result.kind,request,result.revision,before_tick,result.tick};auto valid=validate_task_message_return_results(x);if(!valid.ok)for(auto* target:changes)target->reset();return valid;}
}
